import {TOWERS,statsFor,build,upgrade,sell} from './towers.js';
import {ENEMIES} from './data/enemies.js';
import {LEVELS,REGIONS} from './levels.js';
import {HEROES} from './hero.js';
import {ITEMS,useItem} from './shop.js';
import {totalStars,spentStars,exportSave,importSave} from './save.js';
const $=id=>document.getElementById(id),sprite=id=>`./assets/tiny-dungeon/Tiles/tile_${String(id).padStart(4,'0')}.png`;
export class UI{
 constructor(g){this.g=g;this.modal=$('modal');this.modalPaused=false;this.lastSelection='';this.lastWave='';this.toastTimer=0;g.onNotify=msg=>{clearTimeout(this.toastTimer);$('toast').textContent=msg;$('toast').classList.add('visible');this.toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3000);};g.onFinish=result=>this.result(result);this.buildCards();this.bind();this.refreshLevel();}
 buildCards(){const g=this.g;$('towerCards').innerHTML=Object.entries(TOWERS).map(([key,t],i)=>`<button class="tower-card" data-tower="${key}" title="${t.desc}"><kbd>${i+1}</kbd><span class="tower-art"><img src="${sprite(t.sprite)}" alt=""></span><span class="tower-text"><strong>${t.name}</strong><small>${t.short}</small></span><span class="tower-price">${t.tiers[0].cost} ◈</span></button>`).join('');document.querySelectorAll('[data-tower]').forEach(b=>b.onclick=()=>{if(g.paused||g.outcome)return;g.buildType=b.dataset.tower;if(g.selection?.kind==='plot')build(g,g.buildType,g.selection.index);else g.notify('Choose a marked build plot');this.lastSelection='';this.update();});$('supplyButtons').innerHTML=Object.entries(ITEMS).map(([key,t])=>`<button class="supply" data-item="${key}" title="${t.name}: ${t.desc} Costs ${t.cost} gems." aria-label="${t.name}, ${t.cost} gems"><span>${t.icon}</span><small>${t.cost} ◇</small></button>`).join('');document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{useItem(g,b.dataset.item);this.update();});}
 bind(){const g=this.g;$('waveButton').onclick=()=>g.action('wave');$('pauseButton').onclick=()=>{if(!g.outcome)g.paused=!g.paused;this.update();};$('resumeButton').onclick=()=>{g.paused=false;this.update();};$('speedButton').onclick=()=>{g.speed=g.speed%3+1;this.update();};$('qButton').onclick=()=>g.action('q');$('wButton').onclick=()=>g.action('w');$('soundButton').onclick=()=>{g.save.settings.sound=!g.save.settings.sound;g.audio.set(g.save.settings.sound);g.persist();this.update();};$('campaignButton').onclick=()=>this.campaign();$('upgradesButton').onclick=()=>this.council();$('codexButton').onclick=()=>this.codex();$('settingsButton').onclick=()=>this.settings();$('helpButton').onclick=()=>this.help();$('closeModal').onclick=()=>this.close();this.modal.addEventListener('cancel',e=>{e.preventDefault();this.close();});document.addEventListener('keydown',e=>{if(this.modal.open||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;const key=e.key.toLowerCase();if(key===' '){e.preventDefault();$('pauseButton').click();}if(key==='q'||key==='w')g.action(key);if(key==='n')g.action('wave');if(key==='escape'){g.targeting=null;g.selection=null;g.buildType=null;}if(['1','2','3','4'].includes(key))document.querySelectorAll('[data-tower]')[Number(key)-1].click();});window.addEventListener('pagehide',()=>g.persist());}
 refreshLevel(){const g=this.g,r=REGIONS[g.level.region];$('regionName').textContent=`${['I','II','III'][g.level.region]} / ${r.name.toUpperCase()}`;$('levelName').innerHTML=`${g.level.name}<span class="heading-rule"></span>`;$('levelDescription').textContent=g.level.intro||r.intro;$('missionNumber').textContent=String(g.levelIndex+1).padStart(2,'0');$('difficultyBadge').textContent=g.difficulty.toUpperCase();$('mapCaption').textContent=g.level.name.toUpperCase()+' CROSSING';$('battleWeather').textContent=r.sky+' · LIGHT FOG';$('heroName').textContent=g.hero.name;$('heroTitle').textContent=g.hero.title.toUpperCase();$('heroPortrait').src=sprite(g.hero.sprite);$('heroPortrait').alt=g.hero.name;$('qLabel').textContent=HEROES[g.save.hero].q;$('wLabel').textContent=HEROES[g.save.hero].w;$('qButton').title=HEROES[g.save.hero].q+' · area damage around your hero';$('wButton').title=HEROES[g.save.hero].w+' · empower nearby defenders';this.lastSelection='';this.lastWave='';this.update();}
 update(){const g=this.g;$('lives').textContent=g.lives;$('gold').textContent=Math.floor(g.gold);$('wave').textContent=`${g.wave} / ${g.waveList.length}`;$('gems').textContent=g.save.gems;$('starCount').textContent=`${totalStars(g.save)-spentStars(g.save)} ✦`;$('speedButton').textContent=`${g.speed}×`;$('pauseButton').textContent=g.paused?'▶':'Ⅱ';$('pauseButton').setAttribute('aria-label',g.paused?'Resume':'Pause');$('pauseOverlay').hidden=!g.paused||this.modal.open||!!g.outcome;$('soundButton').textContent=g.save.settings.sound?'♫':'♪';$('soundButton').setAttribute('aria-pressed',String(g.save.settings.sound));$('heroHealth').style.width=`${Math.max(0,g.hero.hp/g.hero.maxHP*100)}%`;$('heroLevel').textContent=g.hero.hp>0?`LV. ${g.hero.level}`:`${Math.ceil(g.hero.respawn)}s`;
 for(const key of ['q','w']){$(key+'Button').disabled=g.hero[key]>0||g.hero.hp<=0||g.paused||!!g.outcome;$(key+'Cooldown').textContent=g.hero[key]>0?`${Math.ceil(g.hero[key])}s`:'';}
 document.querySelectorAll('[data-tower]').forEach(b=>{b.classList.toggle('selected',b.dataset.tower===g.buildType);b.disabled=g.gold<TOWERS[b.dataset.tower].tiers[0].cost||g.paused||!!g.outcome||(g.difficulty==='iron'&&['barracks','artillery'].includes(b.dataset.tower));});document.querySelectorAll('[data-item]').forEach(b=>b.disabled=g.save.gems<ITEMS[b.dataset.item].cost||g.paused||!!g.outcome);
 const next=g.waveList[g.wave];$('waveButton').disabled=!next||(g.wave>0&&!g.intermission)||g.paused||!!g.outcome;$('waveButton').firstElementChild.textContent=g.wave===0?'Call the first wave':!next?'Final wave underway':g.intermission>0?`Call wave ${g.wave+1} · +${Math.ceil(g.intermission*.8)} ◈`:'Hold the line';$('waveHint').textContent=g.intermission>0?`Next wave in ${Math.ceil(g.intermission)}s · call early for bonus gold.`:g.wave===0?'Build your defenses before the march begins.':`${g.enemies.length+g.queue.length} enemies remain · N to call next wave`;
 const waveKey=g.wave+'-'+g.levelIndex;if(this.lastWave!==waveKey){this.lastWave=waveKey;$('previewNumber').textContent=next?String(g.wave+1).padStart(2,'0'):'—';$('wavePreview').innerHTML=next?next.map(p=>`<img src="${sprite(ENEMIES[p.type].sprite)}" alt=""><span title="${ENEMIES[p.type].desc}">${p.count} ${ENEMIES[p.type].name}${p.count>1?'s':''}</span>`).join(''):'The last march is upon us.';}
 const t=g.towers.find(t=>g.selection?.kind==='tower'&&t.id===g.selection.id),key=JSON.stringify([g.selection,t?.tier,t?.branch,Math.floor(g.gold),g.paused]);if(this.lastSelection!==key){this.lastSelection=key;this.selection(t);}}
 selection(t){const g=this.g,p=$('selectionPanel');p.innerHTML='';$('selectionHelp').textContent=g.selection?.kind==='plot'?'Plot selected. Choose a defense to build.':'Select a tower, then choose a build plot.';if(t){const data=TOWERS[t.type],s=statsFor(t);$('selectionHelp').textContent=`${t.branch?data.branches[t.branch].name:data.name} · Tier ${t.branch?4:t.tier+1}`;p.innerHTML=`<div class="selection-stat"><span>${s.damage[0]}–${s.damage[1]} damage</span><span>${s.rate}s · ${s.range} range</span></div>`;if(!t.branch){const opts=t.tier<2?[['next',data.tiers[t.tier+1]]]:Object.entries(data.branches);for(const [branch,next]of opts){const b=document.createElement('button');b.textContent=`${next.name||'Upgrade to tier '+(t.tier+2)} · ${next.cost} ◈`;b.disabled=g.gold<next.cost||g.paused;b.onclick=()=>{upgrade(g,t,branch);this.update();};p.append(b);}}if(t.type==='barracks'||t.branch==='soulforge'){const b=document.createElement('button');b.textContent='⚑ Move rally point';b.onclick=()=>{g.targeting='rally';g.notify('Click the road inside the rally radius');};p.append(b);}const b=document.createElement('button');b.className='danger';b.textContent=`Sell · refund ${Math.floor(t.spent*.7)} ◈`;b.onclick=()=>{sell(g,t);this.update();};p.append(b);}if(g.selection?.kind==='enemy'){const e=g.enemies.find(e=>e.id===g.selection.id);if(e)p.innerHTML=`<p><b>${e.name}</b><br>${e.desc}</p><div class="selection-stat"><span>${Math.ceil(e.hp)} / ${e.maxHP} HP</span><span>${e.bounty} gold</span></div>`;}}
 open(eyebrow,html){if(!this.modal.open){this.modalPaused=this.g.paused;this.g.paused=true;this.modal.showModal();}$('modalEyebrow').textContent=eyebrow;$('modalBody').innerHTML=html;this.update();}
 close(){this.modal.close();if(!this.g.outcome)this.g.paused=this.modalPaused;this.update();}
 start(index){this.modal.close();this.g.reset(index);this.refreshLevel();this.g.notify('Choose your defenses. Call the wave when ready.');}
 campaign(){const g=this.g;this.open('THE ASHEN MARCH',`<h2>The road to the keep</h2><p>Eight crossings. Three fallen regions. One last stand.</p><div class="campaign-grid">${LEVELS.map((l,i)=>`<button class="level-card" data-level="${i}" ${i>g.save.unlocked?'disabled':''}><small>${String(i+1).padStart(2,'0')} / ${REGIONS[l.region].name}${l.boss?' · BOSS':''}</small><b>${l.name}</b><span class="stars">${i>g.save.unlocked?'LOCKED':'★'.repeat(g.save.stars[i]||0)+'☆'.repeat(3-(g.save.stars[i]||0))}</span></button>`).join('')}</div>`);document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{const i=+b.dataset.level;if(g.wave>0&&!g.outcome)this.open('LEAVE THIS BATTLE?',`<h2>Return to the road?</h2><p>Starting a mission resets the current battlefield. Earned hero experience and your campaign progress are saved.</p><div class="actions"><button id="keepBattle">Keep fighting</button><button id="leaveBattle">Start ${LEVELS[i].name}</button></div>`);else return this.start(i);$('keepBattle').onclick=()=>this.close();$('leaveBattle').onclick=()=>this.start(i);});}
 council(){const g=this.g,available=totalStars(g.save)-spentStars(g.save),meta=[['towers','Tempered steel','All towers deal 5% more damage per rank.'],['heroes','Unbroken oath','Heroes gain 20 health and 10% damage per rank.'],['economy','War chest','Start every mission with 20 extra gold per rank.']];this.open('THE WAR COUNCIL',`<h2>A stronger last stand</h2><p><b>${available} ✦</b> unspent stars. Upgrades take effect on your next mission.</p><div class="meta-grid">${meta.map(([k,title,desc])=>`<div class="meta-card"><h3>${title}</h3><p>${desc}</p><p>Rank ${g.save.meta[k]} / 5</p><button data-meta="${k}" ${available<g.save.meta[k]+1||g.save.meta[k]>=5?'disabled':''}>${g.save.meta[k]>=5?'Mastered':`Upgrade · ${g.save.meta[k]+1} ✦`}</button></div>`).join('')}</div><h3>Choose your champion</h3><div class="hero-grid">${Object.entries(HEROES).map(([k,h])=>`<button class="hero-card ${g.save.hero===k?'active':''}" data-hero="${k}" ${g.save.unlocked<h.unlock?'disabled':''}><img src="${sprite(h.sprite)}" alt=""><strong>${h.name}</strong><small>${h.title}</small><small>${g.save.unlocked<h.unlock?'Clear mission '+h.unlock:g.save.hero===k?'Selected · next mission':h.q+' / '+h.w}</small></button>`).join('')}</div>`);document.querySelectorAll('[data-meta]').forEach(b=>b.onclick=()=>{g.save.meta[b.dataset.meta]++;g.persist();this.council();});document.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>{g.save.hero=b.dataset.hero;g.persist();this.council();});}
 codex(){this.open('KNOW YOUR ENEMY',`<h2>The field guide</h2><p>Armor resists physical damage. Magic resistance resists spells. Every enemy has a weakness.</p><div class="codex-grid">${Object.values(ENEMIES).map(e=>`<div class="codex-card"><img src="${sprite(e.sprite)}" alt=""><div><strong>${e.name}</strong><p>${e.hp} HP · ${e.bounty} gold<br>${e.desc}</p></div></div>`).join('')}</div>`);}
 settings(){const g=this.g;this.open('YOUR CAMPAIGN',`<h2>Settings & saves</h2><div class="settings-row"><label for="difficulty">Difficulty for your next mission</label><select id="difficulty"><option value="easy">Easy · 80% enemy health</option><option value="normal">Normal · 100% enemy health</option><option value="hard">Hard · 120% enemy health</option><option value="iron" ${g.save.stars[7]?'':'disabled'}>Iron · one life, archers / magic${g.save.stars[7]?'':' · beat the campaign to unlock'}</option></select></div><p>Progress is saved automatically on this browser. Export a backup to move your campaign to another device. Active battles restart when you reopen the game.</p><label for="saveString">Campaign backup</label><textarea id="saveString" spellcheck="false" aria-label="Save export or import string"></textarea><div class="actions"><button id="exportButton">Export save</button><button id="copyButton">Copy</button><button id="importButton">Import save</button></div><p id="saveStatus" role="status"></p>`);$('difficulty').value=g.save.settings.difficulty;$('difficulty').onchange=e=>{g.save.settings.difficulty=e.target.value;g.persist();};$('exportButton').onclick=()=>{$('saveString').value=exportSave(g.save);$('saveStatus').textContent='Backup ready. Copy and keep this string.';};$('copyButton').onclick=async()=>{try{if(!$('saveString').value)$('saveString').value=exportSave(g.save);await navigator.clipboard.writeText($('saveString').value);$('saveStatus').textContent='Copied to clipboard.';}catch{$('saveString').select();$('saveStatus').textContent='Press Ctrl+C or ⌘C to copy the selected backup.';}};$('importButton').onclick=()=>{try{g.save=importSave($('saveString').value);g.audio.set(g.save.settings.sound);this.start(0);g.notify('Campaign restored');}catch(e){$('saveStatus').textContent='Could not import: '+e.message;}};}
 help(){this.open('A FIELD MANUAL',`<h2>Hold the last road home.</h2><div class="tutorial-grid"><div><h3>Raise your defenses</h3><p>Choose a tower, then click a <b>+ build plot</b>. Select a built tower for upgrades, branches, selling, and rally points. Keys <b>1–4</b> select tower types.</p></div><div><h3>Command your hero</h3><p>Click open ground to move. Your hero attacks and blocks nearby enemies. <b>Q</b> strikes the area around your hero; <b>W</b> raises a banner that empowers nearby defenders.</p></div><div><h3>Control the march</h3><p>Press <b>N</b> or the wave button when ready. Calling during the 20-second break earns gold and reduces ability cooldowns. <b>Space</b> pauses. The speed button cycles 1× / 2× / 3×.</p></div><div><h3>Make every life count</h3><p>Keep 18 lives for three stars, 10 for two. Spend stars at the War Council. Gems buy field supplies. Meteor and militia need a target; <b>Esc</b> cancels targeting.</p></div></div><p>Tip: an Archer Spire on the first bend and Barracks near the second bend make a dependable opening. Add magic when the Blightclad arrive.</p>`);}
 result(r){const g=this.g;this.open(r.victory?'THE ROAD HOLDS':'THE GATE HAS FALLEN',`<h2>${r.victory?'Dawn will find us standing.':'Even stone can break.'}</h2><div class="result-stars">${r.victory?'★'.repeat(r.stars)+'☆'.repeat(3-r.stars):'⚔'}</div><p>${r.victory?`${g.level.name} is safe. Your people march another day.`:'Rethink your positions, use your abilities, and try again.'}</p><div class="result-stats"><span>${g.lives} lives remaining</span><span>${g.kills} defeated</span><span>+${r.gems} gems</span></div><div class="actions"><button id="retryButton">Replay mission</button><button id="resultCampaign">Campaign map</button>${r.victory&&g.levelIndex<7?'<button id="nextMission" class="primary">Next mission →</button>':''}</div>${r.victory&&g.levelIndex===7?'<p>Campaign complete. Iron difficulty is now unlocked in Settings.</p>':''}`);$('retryButton').onclick=()=>this.start(g.levelIndex);$('resultCampaign').onclick=()=>this.campaign();if($('nextMission'))$('nextMission').onclick=()=>this.start(g.levelIndex+1);}
}
